  if(o.type==='box'){var row=o.layout!=='vertical',st='display:flex;flex-direction:'+(row?'row':'column')+';'+(o.layout==='baseline'?'align-items:baseline;':row?'align-items:center;':'')+'gap:'+px(o.spacing||'none')+';'+(o.backgroundColor?'background:'+o.backgroundColor.slice(0,7)+';':'')+(o.cornerRadius?'border-radius:'+px(o.cornerRadius)+';':'')+
    (o.paddingAll?'padding:'+px(o.paddingAll)+';':'')+(o.paddingStart?'padding-left:'+px(o.paddingStart)+';':'')+(o.paddingEnd?'padding-right:'+px(o.paddingEnd)+';':'')+(o.paddingTop?'padding-top:'+px(o.paddingTop)+';':'')+(o.paddingBottom?'padding-bottom:'+px(o.paddingBottom)+';':'')+(o.flex===0?'flex:none;':o.flex?'flex:'+o.flex+';min-width:0;':'')+(o.borderWidth?'border:'+px(o.borderWidth)+' solid '+(o.borderColor||'#ddd')+';':'')+(o.width?'width:'+o.width+';':'')+(o.height?'height:'+o.height+';':'')+(o.justifyContent==='center'?'justify-content:center;':'')+(o.action?'cursor:pointer;':'');
    return '<div style="'+st+'">'+(o.contents||[]).map(fxHtml).join('')+'</div>'}
  if(o.type==='text')return '<div style="font-size:'+(SZ[o.size]||14)+'px;'+(o.weight==='bold'?'font-weight:700;':'')+'color:'+(o.color||'#111').slice(0,7)+';'+(o.color&&o.color.length===9?'opacity:.75;':'')+(o.align?'text-align:'+o.align+';':'')+(o.flex===0?'flex:none;':o.flex?'flex:'+o.flex+';min-width:0;':'')+(o.wrap===false?'white-space:nowrap;':'')+'line-height:1.4">'+esc(o.text)+'</div>';
  if(o.type==='image')return '<img alt="" src="'+esc(/line-logo-white\.png$/.test(o.url||'')?'line-logo-white.png':o.url)+'" style="display:block;width:100%;aspect-ratio:'+String(o.aspectRatio||'1:1').replace(':','/')+';object-fit:contain;object-position:left center">';   // โลโก้: ใช้ไฟล์ข้างหน้าเว็บนี้ (dev ก็เห็น)
